class BlankNodeReferenceHttpJsonRoundTripTest {
	private static final String ACCEPT_JSON = "application/sparql-results+json";

	@Test
	void returnedJsonBlankNodeIdCanBeUsedByASecondHttpQuery() throws Exception {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		DefaultQueryRequestHandler handler = new DefaultQueryRequestHandler(newResolver(repository));
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		IRI object = valueFactory.createIRI("urn:o");
		List<String> ids = List.of("", "json-round-trip-node", "unicode-😟", "delimiter->|^`{}\"\\",
				"space tab\tline\nreturn\rcontrol" + Character.toString(1));

		try (RepositoryConnection connection = repository.getConnection()) {
			for (int index = 0; index < ids.size(); index++) {
				connection.add(valueFactory.createBNode(ids.get(index)), valueFactory.createIRI("urn:p:" + index),
						object);
			}
		}

		try {
			for (int index = 0; index < ids.size(); index++) {
				String predicate = "urn:p:" + index;
				byte[] selectBody = runHttpQuery(handler,
						"SELECT ?node WHERE { ?node <" + predicate + "> <urn:o> }");
				String json = new String(selectBody, StandardCharsets.UTF_8);
				assertTrue(Pattern.compile("\"type\"\\s*:\\s*\"bnode\"").matcher(json).find(),
						"the wire result must encode the value with SPARQL JSON type bnode: " + json);
				QueryResultCollector collector = new QueryResultCollector();
				QueryResultIO.parseTuple(new ByteArrayInputStream(selectBody), TupleQueryResultFormat.JSON, collector,
						valueFactory);
				assertEquals(List.of("node"), collector.getBindingNames());
				assertEquals(1, collector.getBindingSets().size());
				BNode returnedNode = assertInstanceOf(BNode.class,
						collector.getBindingSets().get(0).getValue("node"));
				assertEquals(ids.get(index), returnedNode.getID(), "JSON must preserve the exact blank-node ID");

				String reference = RenderUtils.toSPARQL(returnedNode);
				byte[] askBody = runHttpQuery(handler,
						"ASK { " + reference + " <" + predicate + "> <urn:o> }");
				assertTrue(QueryResultIO.parseBoolean(new ByteArrayInputStream(askBody), BooleanQueryResultFormat.JSON),
						"the exact JSON identity must resolve in a second real handler request");
			}
		} finally {
			handler.shutdown();
			repository.shutDown();
		}
	}

	private static RepositoryResolver newResolver(Repository repository) {
		RepositoryResolver resolver = mock(RepositoryResolver.class);
		when(resolver.getRepository(any())).thenReturn(repository);
		when(resolver.getRepositoryID(any())).thenReturn("blank-node-reference-json-test");
		when(resolver.getRepositoryConnection(any(), eq(repository))).thenAnswer(ignored -> repository.getConnection());
		return resolver;
	}

	private static byte[] runHttpQuery(DefaultQueryRequestHandler handler, String query) throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setMethod(RequestMethod.POST.name());
		request.setContentType(Protocol.FORM_MIME_TYPE);
		request.setParameter(Protocol.QUERY_PARAM_NAME, query);
		request.addHeader("Accept", ACCEPT_JSON);
		MockHttpServletResponse response = new MockHttpServletResponse();

		ModelAndView modelAndView = handler.handleQueryRequest(request, RequestMethod.POST, response);
		assertEquals(200, response.getStatus());
		modelAndView.getView().render(modelAndView.getModel(), request, response);
		assertEquals(200, response.getStatus());
		return response.getContentAsByteArray();
	}
}
